package com.newuniverse.nusmp.vfx.client.layer;

import com.newuniverse.nusmp.vfx.client.VfxBlend;
import com.newuniverse.nusmp.vfx.client.VfxTextures;
import com.newuniverse.nusmp.vfx.client.VfxVertexBuffer;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import org.joml.Vector3f;

/**
 * 1.93.0 The sprite tables and small drawing helpers of {@link EarthFamilyLayer}: for each of the six magics (EarthFxStyle order: Sandstone, Rock, Red Ochre,
 * Stone, Earth, Mineral) the five sprites that give it its identity, generated by tools/gen_earth_family_textures.py.
 * <pre>
 *   DEBRIS  what flies and falls     slab chip, rock chunk, pigment drop, masonry block, soil clod, crystal shard
 *   PUFF    the soft body            sand haze, grey dust, ochre splat, stone dust, earth dust, crystal facet
 *   SIGIL   the ground sigil         hourglass circle, jagged triangle, sun glyph, runic circle, gnome circle, hex lattice
 *   ACCENT  the signature element    falling sand, ground fissures, handprint, rune, root, four-point glint
 *   SPARK   the small bright bits    sand grain, rock chunk, pigment drop, stone shard, grass blade, glint
 * </pre>
 */
final class EarthFamilyFx {
    private EarthFamilyFx() {}

    private static ResourceLocation t(String key, String name) { return VfxTextures.byName("earthfam_" + key + "_" + name); }

    static final ResourceLocation[] DEBRIS = {t("sandstone", "slab"), t("rock", "chunk"), t("red_ochre", "drop"), t("stone", "block"), t("earth", "clod"), t("mineral", "shard")};
    static final ResourceLocation[] PUFF = {t("sandstone", "haze"), t("rock", "dust"), t("red_ochre", "splat"), t("stone", "dust"), t("earth", "dust"), t("mineral", "facet")};
    static final ResourceLocation[] SIGIL = {t("sandstone", "sigil"), t("rock", "sigil"), t("red_ochre", "sun"), t("stone", "circle"), t("earth", "circle"), t("mineral", "circle")};
    static final ResourceLocation[] ACCENT = {t("sandstone", "stream"), t("rock", "crack"), t("red_ochre", "hand"), t("stone", "rune"), t("earth", "root"), t("mineral", "flare")};
    static final ResourceLocation[] SPARK = {t("sandstone", "grain"), t("rock", "chunk"), t("red_ochre", "drop"), t("stone", "shard"), t("earth", "blade"), t("mineral", "flare")};
    static final ResourceLocation TRAIL = t("all", "trail");
    /** The impact rings of the two magics that have one drawn (Rock: debris ring, Mineral: crystals standing on the ring). */
    static final ResourceLocation ROCK_RING = t("rock", "ring"), MINERAL_RING = t("mineral", "ring"), MINERAL_SHARD = t("mineral", "shard"), EARTH_BLADE = t("earth", "blade"),
            SAND_STREAM = t("sandstone", "stream"), OCHRE_STRIPE = t("red_ochre", "stripe");

    static int a(int argb, float k) { return VfxVertexBuffer.withAlpha(argb, Mth.clamp(k, 0f, 1f)); }

    static float sm(float e0, float e1, float x) {
        float k = Mth.clamp((x - e0) / (e1 - e0), 0, 1);
        return k * k * (3 - 2 * k);
    }

    /** A unit vector from two hashes: uniform on the sphere when up = false, on the upper hemisphere when up = true. */
    static Vector3f dirOf(float u, float v, boolean up) {
        float z = up ? 0.12f + 0.88f * u : u * 2f - 1f;
        float s = Mth.sqrt(Math.max(0f, 1f - z * z)), ang = v * Mth.TWO_PI;
        return new Vector3f(Mth.cos(ang) * s, z, Mth.sin(ang) * s);
    }

    /** A camera-facing ribbon from a (the texture's bottom) to b (its top): crystals, blades, risers, falling sand. */
    static void strut(VfxVertexBuffer buf, ResourceLocation tex, VfxBlend blend, Vector3f a, Vector3f b, float halfW, int argb) {
        Vector3f dir = new Vector3f(b).sub(a);
        if (dir.lengthSquared() < 1e-6f) return;
        Vector3f mid = new Vector3f(a).add(b).mul(0.5f);
        Vector3f side = new Vector3f(dir).cross(new Vector3f(mid).negate());
        if (side.lengthSquared() < 1e-8f) return;
        side.normalize().mul(halfW);
        int col = blend.grade(argb, 0.8f);
        buf.quad(tex, blend, new Vector3f(a).sub(side), new Vector3f(a).add(side), new Vector3f(b).add(side), new Vector3f(b).sub(side), 0, 0, 1, 1, col, col);
    }

    /** A sprite lying on the ground, its +u end pointing along 'heading' (radians in the x / z plane). */
    static void flat(VfxVertexBuffer buf, ResourceLocation tex, VfxBlend blend, Vector3f c, float heading, float len, float wid, int argb) {
        float fx = Mth.cos(heading), fz = Mth.sin(heading);
        Vector3f f = new Vector3f(fx * len * 0.5f, 0, fz * len * 0.5f), s = new Vector3f(-fz * wid * 0.5f, 0, fx * wid * 0.5f);
        int col = blend.grade(argb, 0.8f);
        buf.quad(tex, blend, new Vector3f(c).sub(f).add(s), new Vector3f(c).add(f).add(s), new Vector3f(c).add(f).sub(s), new Vector3f(c).sub(f).sub(s), 0, 0, 1, 1, col, col);
    }
}
